/**
 * A nested sub-select is a bottom-up scope boundary: the bindings a correlating operator pushes into it are not in
 * scope inside it. The whole sub-select unit (the projection plus the DISTINCT/REDUCED/LIMIT above it) is evaluated
 * once with only the names an enclosing LATERAL substitutes, and its rows are joined with the incoming bindings by
 * compatibility on the projected names afterwards. EXISTS substitution follows the same scoping: only the variables a
 * sub-select projects are substituted inside it.
 */
class NestedSubSelectScopeBoundaryTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI R = iri("r");
	private static final IRI Z = iri("z");

	private static IRI iri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	private static Var constant(String name, Value value) {
		return Var.of(name, value, false, true);
	}

	private static StatementPattern pattern(String subject, IRI predicate, String object) {
		return new StatementPattern(Var.of(subject), constant("_const_" + predicate.getLocalName(), predicate),
				Var.of(object));
	}

	private static Statement st(String s, IRI p, Value o) {
		return VF.createStatement(iri(s), p, o);
	}

	private static Projection projection(TupleExpr arg, String... names) {
		ProjectionElemList elements = new ProjectionElemList();
		for (String name : names) {
			elements.addElement(new ProjectionElem(name));
		}
		return new Projection(arg, elements);
	}

	private static BindingSet bindings(Object... namesAndValues) {
		QueryBindingSet bindings = new QueryBindingSet();
		for (int i = 0; i < namesAndValues.length; i += 2) {
			bindings.addBinding((String) namesAndValues[i], (Value) namesAndValues[i + 1]);
		}
		return bindings;
	}

	private static final List<Statement> R_DATA = List.of(
			st("c", R, VF.createLiteral(1)),
			st("d", R, VF.createLiteral(2)),
			st("e", R, VF.createLiteral(3)));

	@Test
	void nestedSubSelectDoesNotSeeIncomingBindingsOfVariablesItDoesNotProject() {
		// { SELECT ?t WHERE { ?t :r ?x } } as the right arg of a Join: inside it ?x is fresh
		Projection unit = projection(pattern("t", R, "x"), "t");
		new Join(pattern("s", iri("p"), "x"), unit);

		List<String> rows = evaluateNode(unit, R_DATA, bindings("s", iri("a"), "x", VF.createLiteral(2)));

		assertThat(rows).as("every :r subject is a match; the incoming ?x=2 must not select ?t :r 2")
				.containsExactly(
						"{s=urn:ex:a, t=urn:ex:c, x=2}",
						"{s=urn:ex:a, t=urn:ex:d, x=2}",
						"{s=urn:ex:a, t=urn:ex:e, x=2}");
	}

	@Test
	void projectedNamesAreJoinedByCompatibilityAfterTheSubSelectIsComplete() {
		// { SELECT ?t ?x WHERE { ?t :r ?x } ORDER BY ?x LIMIT 1 }: bottom-up the unit is exactly {t=c, x=1}
		Projection projection = projection(new Order(pattern("t", R, "x"), List.of(new OrderElem(Var.of("x")))), "t",
				"x");
		Slice unit = new Slice(projection, -1, 1);
		new Join(pattern("s", iri("p"), "x"), unit);

		List<String> rows = evaluateNode(unit, R_DATA, bindings("s", iri("a"), "x", VF.createLiteral(2)));

		assertThat(rows).as("LIMIT 1 keeps {t=c, x=1}, which is incompatible with the incoming ?x=2").isEmpty();
	}

	@Test
	void compatibleProjectedRowsAreMergedAndConflictingRowsAreDroppedNotOverwritten() {
		Projection unit = projection(pattern("t", R, "x"), "t", "x");
		new Join(pattern("s", iri("p"), "x"), unit);

		List<String> rows = evaluateNode(unit, R_DATA, bindings("s", iri("a"), "x", VF.createLiteral(2)));

		assertThat(rows).as("only the row with x=2 is compatible; rows with x=1 and x=3 must not overwrite x")
				.containsExactly("{s=urn:ex:a, t=urn:ex:d, x=2}");
	}

	@Test
	void subSelectUnderAnExistsHolderIsNested() {
		Projection unit = projection(pattern("t", R, "x"), "t");
		new Exists(unit);

		List<String> rows = evaluateNode(unit, R_DATA, bindings("x", VF.createLiteral(2)));

		assertThat(rows).hasSize(3);
	}

	@Test
	void topLevelProjectionKeepsPassingIncomingBindingsThrough() {
		Projection unit = projection(pattern("t", R, "x"), "t");
		new QueryRoot(unit);

		List<String> rows = evaluateNode(unit, R_DATA, bindings("x", VF.createLiteral(2)));

		assertThat(rows).as("external bindings are constants in the whole query and reach a top-level projection")
				.containsExactly("{t=urn:ex:d}");
	}

	@Test
	void topLevelSliceAboveProjectionKeepsPassingIncomingBindingsThrough() {
		Slice unit = new Slice(projection(pattern("t", R, "x"), "t"), -1, 5);
		new QueryRoot(unit);

		List<String> rows = evaluateNode(unit, R_DATA, bindings("x", VF.createLiteral(2)));

		assertThat(rows).containsExactly("{t=urn:ex:d}");
	}

	@Test
	void lateralSubstitutedNamesArePushedIntoTheSubSelect() {
		// LATERAL { SELECT ?t ?x WHERE { ?t :r ?x } LIMIT 1 } with ?x substituted from the left row
		Slice unit = new Slice(projection(pattern("t", R, "x"), "t", "x"), -1, 1);
		new Lateral(new SingletonSet(), unit, Set.of("x"));

		List<String> rows = evaluateNode(unit, R_DATA, bindings("x", VF.createLiteral(2)));

		assertThat(rows).as("the substituted ?x is a constant inside the right-hand side, so LIMIT 1 sees ?t :r 2")
				.containsExactly("{t=urn:ex:d, x=2}");
	}

	@Test
	void subSelectAsLeftArgOfAJoinInsideAnOptionalIsEvaluatedBottomUp() {
		// ?s :p ?x OPTIONAL { { SELECT ?t ?x WHERE { ?t :r ?x } ORDER BY ?x LIMIT 1 } ?t :z ?y }
		List<Statement> data = new ArrayList<>(R_DATA);
		data.add(st("a", iri("p"), VF.createLiteral(2)));
		data.add(st("d", Z, iri("y1")));
		Projection projection = projection(new Order(pattern("t", R, "x"), List.of(new OrderElem(Var.of("x")))), "t",
				"x");
		Slice unit = new Slice(projection, -1, 1);
		LeftJoin leftJoin = new LeftJoin(pattern("s", iri("p"), "x"), new Join(unit, pattern("t", Z, "y")));
		QueryRoot root = new QueryRoot(leftJoin);

		List<String> rows = evaluateNode(root, data, EmptyBindingSet.getInstance());

		assertThat(rows).as("the sub-select is {t=c, x=1}; :c has no :z edge, so the left row stays bare")
				.containsExactly("{s=urn:ex:a, x=2}");
	}

	@Test
	void existsSubstitutionReplacesVisibleVariablesOnly() {
		// ?s :q ?v FILTER(?v = ?o) { SELECT ?t WHERE { ?t :r ?x { SELECT ?t ?x WHERE { ?t :z ?x } } } }
		StatementPattern outerPattern = pattern("s", iri("q"), "v");
		Compare compare = new Compare(Var.of("v"), Var.of("o"), Compare.CompareOp.EQ);
		StatementPattern projectedPattern = pattern("t", R, "x");
		StatementPattern innerPattern = pattern("t", Z, "x");
		Projection inner = projection(innerPattern, "t", "x");
		Projection outer = projection(new Join(projectedPattern, inner), "t");
		Filter body = new Filter(new Join(outerPattern, outer), compare);
		BindingSet outerRow = bindings("s", iri("a"), "o", iri("o1"), "t", iri("t1"), "x", VF.createLiteral(1),
				"v", VF.createLiteral(7));

		BindingAssignerOptimizer.substituteInScope(body, outerRow);

		assertThat(outerPattern.getSubjectVar().getValue()).as("outside any sub-select every bound var is replaced")
				.isEqualTo(iri("a"));
		assertThat(outerPattern.getObjectVar().getValue()).isEqualTo(VF.createLiteral(7));
		assertThat(((Var) compare.getLeftArg()).getValue()).isEqualTo(VF.createLiteral(7));
		assertThat(((Var) compare.getRightArg()).getValue()).isEqualTo(iri("o1"));
		assertThat(projectedPattern.getSubjectVar().getValue()).as("?t is projected by the outer sub-select")
				.isEqualTo(iri("t1"));
		assertThat(projectedPattern.getObjectVar().hasValue()).as("?x is fresh inside the outer sub-select")
				.isFalse();
		assertThat(innerPattern.getSubjectVar().getValue()).as("?t stays visible through both projections")
				.isEqualTo(iri("t1"));
		assertThat(innerPattern.getObjectVar().hasValue())
				.as("the inner sub-select projects ?x, but the outer one hides it, so ?x is fresh there too")
				.isFalse();
	}

	@Test
	void existsSubstitutionLeavesTheOriginalExpressionUntouchedWhenNothingIsBound() {
		StatementPattern pattern = pattern("t", R, "x");
		Projection unit = projection(pattern, "t");

		BindingAssignerOptimizer.substituteInScope(unit, EmptyBindingSet.getInstance());

		assertThat(pattern.getSubjectVar().hasValue()).isFalse();
		assertThat(pattern.getObjectVar().hasValue()).isFalse();
	}

	private static List<String> evaluateNode(TupleExpr node, List<Statement> data, BindingSet bindings) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new ListTripleSource(data), null);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal(null);
		QueryEvaluationStep step = strategy.precompile(node, context);
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = step.evaluate(bindings)) {
			while (iteration.hasNext()) {
				BindingSet row = iteration.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : row.getBindingNames()) {
					Value value = row.getValue(name);
					if (value != null) {
						sorted.put(name, value.stringValue());
					}
				}
				rows.add(sorted.toString());
			}
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}

	private static final class ListTripleSource implements TripleSource {
		private final List<Statement> statements;

		private ListTripleSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subj == null || subj.equals(statement.getSubject()))
					.filter(statement -> pred == null || pred.equals(statement.getPredicate()))
					.filter(statement -> obj == null || obj.equals(statement.getObject()))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}

		@Override
		public Comparator<Value> getComparator() {
			return null;
		}
	}
}
